<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();$id=(int)($_GET['id']??$_POST['id']??0);$cot=srnu_obtener_cotizacion($id);if(!$cot){http_response_code(404);exit('Cotización no encontrada');}
if($_SERVER['REQUEST_METHOD']==='POST'){foreach(['Sergio','Ricardo','Tomás'] as $p){$k=mb_strtolower(str_replace('á','a',$p));$m=max(0,(float)($_POST['monto_'.$k]??0));$pdo->prepare('INSERT INTO reparto_ajustes(cotizacion_id,persona,monto_objetivo,notas) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE monto_objetivo=VALUES(monto_objetivo),notas=VALUES(notas)')->execute([$id,$p,$m,epost('notas_'.$k)]);}ego('reparto.php?id='.$id);}
$base=srnu_reparto_interno_conceptos($cot['items']);$targets=['Sergio'=>$base['sergio'],'Ricardo'=>$base['ricardo'],'Tomás'=>$base['tomas']];$s=$pdo->prepare('SELECT * FROM reparto_ajustes WHERE cotizacion_id=?');$s->execute([$id]);$adj=[];foreach($s as $r)$adj[$r['persona']]=$r;$s=$pdo->prepare("SELECT destinatario,COALESCE(SUM(monto),0) total FROM pagos WHERE cotizacion_id=? GROUP BY destinatario");$s->execute([$id]);$paid=[];foreach($s as $r)$paid[$r['destinatario']]=(float)$r['total'];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reparto · SRNU</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('finanzas');?><main class="w"><div class="srnu-page-heading"><div><h1>Reparto final</h1><p><?=eh($cot['folio'])?> · <?=eh($cot['cliente'])?> · <?=eh($cot['vehiculo'])?></p></div><a class="btn light" href="cotizaciones.php">← Cotizaciones</a></div><section class="panel" style="padding:18px"><p class="muted">El cálculo base usa los responsables asignados a cada concepto. Si un trabajo se repartió distinto al cálculo automático, puedes fijar aquí el monto objetivo final por integrante.</p><form method="post"><input type="hidden" name="id" value="<?=$id?>"><div class="grid-3"><?php foreach($targets as $p=>$b):$t=isset($adj[$p])?(float)$adj[$p]['monto_objetivo']:(float)$b;$rec=(float)($paid[$p]??0);$pend=max(0,$t-$rec);$k=mb_strtolower(str_replace('á','a',$p));?><div class="card"><span class="srnu-stat-accent"></span><h2><?=eh($p)?></h2><p>Base por conceptos: <b><?=emoney($b)?></b></p><label>Monto objetivo final<input type="number" step="0.01" min="0" name="monto_<?=$k?>" value="<?=number_format($t,2,'.','')?>"></label><label>Notas<input name="notas_<?=$k?>" value="<?=eh($adj[$p]['notas']??'')?>"></label><p>Recibido registrado: <b><?=emoney($rec)?></b></p><p>Pendiente: <b><?=emoney($pend)?></b></p></div><?php endforeach;?></div><button class="btn blue" style="margin-top:14px" name="guardar" value="1">Guardar reparto final</button></form></section><div class="kpi-grid" style="margin-top:16px"><div class="kpi"><small>Subtotal servicios</small><strong><?=emoney($cot['subtotal'])?></strong></div><div class="kpi"><small>IVA</small><strong><?=emoney($cot['iva'])?></strong></div><div class="kpi"><small>Total</small><strong><?=emoney($cot['total'])?></strong></div><div class="kpi"><small>Pagado total</small><strong><?=emoney(srnu_total_pagado($id))?></strong></div></div></main></body></html>
